def stop_reason(history, *, max_iters=50, stale_cap=3):
    """history holds one dict per finished iteration, in order, with keys spec_moved (bool),
    new_commits (int) and all_pass (bool). Return (iteration, reason) for the first iteration
    after which the driver stops, reason one of "spec_moved", "completed", "no_progress" or
    "max_iters"; return None if the loop would go on."""
    stale = 0
    for i, it in enumerate(history, start=1):
        if it["spec_moved"]:
            return i, "spec_moved"
        if it["all_pass"]:
            return i, "completed"
        stale = 0 if it["new_commits"] else stale + 1
        if stale >= stale_cap:
            return i, "no_progress"
        if i >= max_iters:
            return i, "max_iters"
    return None
